export function collectDatedEntries(entries, records = details) {
  return Array.from(entries).flatMap(entry => (records[entry.id]?.dates || [])
    .filter(date => Number.isFinite(date.start) && Number.isFinite(date.end ?? date.start) && (date.end ?? date.start) >= date.start && date.source?.url)
    .map((date, index) => ({ ...date, end: date.end ?? date.start, entryId: entry.id, entryTitle: entry.title, type: entry.type, key: `${entry.id}-${index}` })))
    .sort((a, b) => a.start - b.start || a.end - b.end || a.key.localeCompare(b.key));
}

export function normalizeSearch(value) {
  return String(value).toLocaleLowerCase('fr').normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '').replace(/œ/g, 'oe').replace(/æ/g, 'ae')
    .replace(/[‘’]/g, "'").replace(/[-‐‑–—]/g, ' ').replace(/\s+/g, ' ').trim();
}

export function searchEntries(entries, query, records = details) {
  const normalize = normalizeSearch;
  const needle = normalize(query);
  if (!needle) return [];
  const words = needle.split(/\s+/);
  return Array.from(entries).map(entry => {
    const title = normalize(entry.title);
    const content = records[entry.id];
    const corpus = normalize(`${entry.title} ${entry.type} ${entry.shortDescription} ${content?.kicker || ''} ${(content?.dates || []).map(date => `${date.label} ${date.title} ${date.place}`).join(' ')}`);
    const rank = title === needle ? 0 : title.startsWith(needle) ? 1 : title.includes(needle) ? 2 : 3;
    return { entry, rank, matches: words.every(word => corpus.includes(word)) };
  }).filter(result => result.matches).sort((a, b) => a.rank - b.rank || a.entry.title.localeCompare(b.entry.title, 'fr')).map(result => result.entry);
}
